programa
{
    funcao inicio()
    {
        inteiro x, n, i, posicao
        inteiro seq[20]

        escreva("Valor procurado: ")
        leia(x)
        escreva("Quantos numeros? ")
        leia(n)

        para (i = 0; i < n; i++)
        {
            leia(seq[i])
        }

        posicao = n
        para (i = 0; i < n; i++)
        {
            se (x == seq[i])
            {
                posicao = i
                pare
            }
            se (x < seq[i])
            {
                posicao = i
                pare
            }
        }

        escreva("Indice = ", posicao, "\n")
    }
}
